    <div className="library-toolbar"><label className="input-search"><Search size={17} /><input aria-label="Games zoeken" placeholder="Zoek een game…" value={search} onChange={e => setSearch(e.target.value)} /><kbd>/</kbd></label><button className={`button secondary ${onlyFavorites ? 'selected' : ''}`} onClick={() => setOnlyFavorites(!onlyFavorites)}><Star size={15} fill={onlyFavorites ? 'currentColor' : 'none'} />Favorieten</button><select aria-label="Games sorteren" className="select" value={sort} onChange={e => setSort(e.target.value)}><option value="name">Naam A–Z</option><option value="recent">Laatst gestart</option></select><div className="segmented"><IconButton icon={LayoutGrid} label="Rasterweergave" className={!list ? 'active' : ''} onClick={() => setList(false)} /><IconButton icon={List} label="Lijstweergave" className={list ? 'active' : ''} onClick={() => setList(true)} /></div></div>
