function Apps({ state, run, goService }) { return <><div className="page-heading"><div><div className="eyebrow"><span className="tiny-line" /> YOUR PEOPLE. YOUR PLATFORMS.</div><h1>Alles blijft verbonden<span className="accent">.</span></h1><p>Je vertrouwde apps, met een eigen plek in Nexus.</p></div></div><div className="apps-grid">{Object.entries(state.services).map(([id, s]) => <section className="app-card" key={id}><div className="app-card-top"><AppMark id={id} color={s.color} size="large" /><span className="pill">WINDOWS APP</span></div><h2>{s.name}</h2><p>{id === 'discord' ? 'De echte Discord-app op je Nexus-scherm. Je bestaande account, servers en voice blijven beschikbaar.' : id === 'whatsapp' ? 'Gebruik de geïnstalleerde WhatsApp-app van Windows met je bestaande gesprekken en aanmelding.' : id === 'spotify' ? 'De geïnstalleerde Spotify-app, inclusief je eigen playlists, podcasts en offline bibliotheek.' : 'Open Xbox Cloud Gaming in je browser, of start de Xbox-app voor je pc-games en partyfuncties.'}</p><div className="app-card-actions"><button className="button primary" onClick={() => id === 'xbox' ? run(() => api.service('external', id)) : goService(id)}>{id === 'xbox' ? 'Desktopapp openen' : 'Open in Nexus'}<ArrowUpRight size={15} /></button></div></section>)}</div><section className="settings-section"><div className="section-title"><LayoutGrid size={18} /><div><h2>Alle launchers binnen handbereik</h2><p>Open je geïnstalleerde clients. Games start je rechtstreeks vanuit de bibliotheek.</p></div></div><div className="launcher-cards">{Object.keys(state.launchers).map(name => <button key={name} onClick={() => run(() => api.launcher(name))}><AppMark name={name} /><span>{name}</span><ArrowUpRight size={16} /></button>)}</div></section></>; }
function ServicePage({ id, definition, status, state, run }) {
  const target = useRef(); const externalOnly = id === 'xbox';
  useEffect(() => {
    if (externalOnly) return;
    let disposed = false;
    const resize = () => { if (target.current && !disposed) { const b = target.current.getBoundingClientRect(); api.serviceBounds({ x: b.x, y: b.y, width: b.width, height: b.height }).catch(() => {}); } };
    run(() => api.service('open', id)).then(resize);
    const observer = new ResizeObserver(resize); if (target.current) observer.observe(target.current);
    window.addEventListener('resize', resize);
    return () => { disposed = true; observer.disconnect(); window.removeEventListener('resize', resize); api.service('hide').catch(() => {}); };
  }, [id]);
  return <><div className="service-toolbar"><div><AppMark id={id} color={definition.color} /><span><h1>{definition.name}</h1><small>{externalOnly ? 'Windows-integratie' : 'Eigen Nexus-app · Sessie lokaal bewaard'}</small></span></div>
    <div>{!externalOnly && <><span className="session-badge"><ShieldCheck size={13} />Eigen sessie</span><IconButton icon={ArrowLeft} label="Terug in app" onClick={() => run(() => api.service('back', id))} /><IconButton icon={RefreshCw} label="App opnieuw laden" onClick={() => run(() => api.service('reload', id))} /></>}</div></div>
    <div ref={target} className="service-view">{externalOnly ? <div className="service-intro"><AppMark id={id} color={definition.color} size="large" /><h2>Een wereld aan games.</h2><p>Start de Xbox-app voor je games en party’s. Xbox Cloud Gaming opent in je browser.</p><button className="button primary" onClick={() => run(() => api.service('external', id))}>Xbox-app starten<ArrowUpRight size={16} /></button><button className="text-link" onClick={() => run(() => api.service('browser', id))}>Open Xbox Cloud Gaming<ExternalLink size={14} /></button></div>
    : status?.error || state.preview ? <Empty icon={Globe} title="De app kon niet worden geladen" text={state.preview ? 'Deze app werkt in de Nexus Hub-desktopapp.' : status.error || 'Controleer je verbinding en probeer opnieuw.'} action="Opnieuw proberen" onClick={() => run(() => api.service('reload', id))} />
    : <div className="service-loading"><RefreshCw size={25} className="spin" /><p>{definition.name} laden…</p></div>}</div></>;
}
function NativeServicePage({ id, definition, status, run, state }) {
  const target = useRef();
  useEffect(() => {
    let disposed = false;
    const resize = () => { if (!disposed && target.current) { const b = target.current.getBoundingClientRect(); api.serviceBounds({ x: b.x, y: b.y, width: b.width, height: b.height }).catch(() => {}); } };
    run(() => api.service('open', id)).then(resize);
    const observer = new ResizeObserver(resize); if (target.current) observer.observe(target.current);
    return () => { disposed = true; observer.disconnect(); api.service('hide').catch(() => {}); };
  }, [id]);
  return <><div className="service-toolbar"><div><AppMark id={id} color={definition.color} /><span><h1>{definition.name}</h1><small>Geïnstalleerde Windows-app · Bestaande aanmelding</small></span></div><div><span className="session-badge"><Monitor size={13} />Windows-app</span><button className="button secondary" onClick={() => run(() => api.service('external', id))}>Los openen<ExternalLink size={14} /></button><button className="button secondary" onClick={() => run(() => api.service('reload', id))}><RefreshCw size={15} />In Nexus plaatsen</button></div></div><div ref={target} className="service-view"><div className="service-intro native-app-card"><AppMark id={id} color={definition.color} size="large" /><h2>{status?.error ? definition.name + ' verbinden' : status?.loading ? 'Windows-app openen…' : definition.name + ' op je Nexus-scherm'}</h2><p>{state.preview ? 'Open Nexus Hub op Windows om je geïnstalleerde apps te gebruiken.' : status?.error || 'Nexus plaatst het echte appvenster in deze ruimte. Je aanmelding en gegevens blijven in de Windows-app. Bij afsluiten van Nexus wordt het venster teruggezet.'}</p>{status?.error && <button className="button primary" onClick={() => run(() => api.service('reload', id))}>Opnieuw proberen</button>}{status?.loading && <RefreshCw size={24} className="spin" />}</div></div></>;
}
function Settings({ state, changeSettings, run }) {
  const s = state.settings; const [name, setName] = useState(s.username);
  return <><div className="page-heading"><div><div className="eyebrow"><span className="tiny-line" /> BUILT AROUND YOU.</div><h1>Maak Nexus van jou<span className="accent">.</span></h1><p>Een tweede scherm dat precies bij je setup past.</p></div><span className="pill">NEXUS HUB {state.version}</span></div><div className="settings-grid">
    <section className="settings-section"><div className="section-title"><Monitor size={20} /><div><h2>Je scherm, jouw cockpit</h2><p>Nexus blijft op het gekozen scherm, ook bij herstart en in overlaymodus.</p></div></div><div className="display-lock-note"><ShieldCheck size={15} /><span>{state.displayTarget?.available === false ? `${state.displayTarget.label} is niet aangesloten. Je keuze blijft bewaard.` : `Vast scherm: ${state.displayTarget?.label || 'kies hieronder je display'}`}</span></div><div className="display-cards">{state.displays.length ? state.displays.map((d, i) => <button key={d.id} className={(state.displayTarget?.activeId ?? s.displayId) === d.id ? 'active' : ''} onClick={() => changeSettings({ displayId: d.id })}><div className="display-illustration"><Monitor size={46} strokeWidth={1} /><span>{i + 1}</span></div><strong>{d.label}</strong><small>{d.width} × {d.height}{d.primary ? ' · Hoofdscherm' : ' · Extra scherm'}</small>{(state.displayTarget?.activeId ?? s.displayId) === d.id && <Check size={15} />}</button>) : <p>Open de desktopapp om je beeldschermen te kiezen.</p>}</div><SettingRow label="Volledig scherm" description="Vul het gekozen scherm. F11 wisselt, Escape keert terug." checked={Boolean(state.fullscreen)} onChange={value => changeSettings({ fullscreen: value })} /><SettingRow label="Altijd op de voorgrond" description="Houd Nexus zichtbaar boven normale vensters." checked={s.alwaysOnTop} onChange={value => changeSettings({ alwaysOnTop: value })} /><button className="text-link" onClick={() => run(() => api.window('display-settings'))}>Windows-beeldscherminstellingen<ExternalLink size={14} /></button></section>
    <section className="settings-section"><div className="section-title"><Sparkles size={20} /><div><h2>De juiste sfeer</h2><p>Rustig, helder en helemaal jouw stijl.</p></div></div><div className="theme-options">{[['mint', 'Arctic mint', '#a7e6c7'], ['violet', 'After hours', '#c0adf1'], ['amber', 'Golden hour', '#eac08c']].map(([id, label, color]) => <button key={id} className={s.theme === id ? 'active' : ''} onClick={() => changeSettings({ theme: id })}><span className="theme-swatch" style={{ '--swatch': color }}><i /><i /><i /></span><span>{label}</span>{s.theme === id && <Check size={14} />}</button>)}</div><div className="setting-row"><div><strong>Weergavedichtheid</strong><p>Meer ruimte of meer informatie op je scherm.</p></div><select aria-label="Weergavedichtheid" className="select" value={s.density} onChange={e => changeSettings({ density: e.target.value })}><option value="comfortable">Comfortabel</option><option value="compact">Compact</option></select></div><SettingRow label="Minder animatie" description="Een stiller dashboard, zonder bewegende effecten." checked={s.reduceMotion} onChange={value => changeSettings({ reduceMotion: value })} /><SettingRow label="Gamehoezen ophalen" description="Toon automatisch gevonden en lokaal bewaarde hoezen. Kies ook zelf een afbeelding per game." checked={s.artwork} onChange={value => changeSettings({ artwork: value })} /></section>
    <section className="settings-section"><div className="section-title"><Settings2 size={20} /><div><h2>Dagelijks gebruik</h2><p>Kleine details die het verschil maken.</p></div></div><div className="setting-row"><div><strong>Hoe mogen we je noemen?</strong><p>Alleen opgeslagen op deze computer.</p></div><input className="text-input name-input" aria-label="Je naam" placeholder="Je voornaam" value={name} maxLength={36} onChange={e => setName(e.target.value)} onBlur={() => changeSettings({ username: name })} onKeyDown={e => { if (e.key === 'Enter') e.target.blur(); }} /></div><SettingRow label="Starten met Windows" description="Werkt zodra Nexus met de installer is geïnstalleerd." checked={s.autostart} onChange={value => changeSettings({ autostart: value })} /><div className="hotkeys"><div><span>Toon / verberg Nexus</span><kbd>Ctrl + Shift + Space</kbd></div><div><span>Compacte overlay</span><kbd>Ctrl + Shift + O</kbd></div><div><span>Zoeken in Nexus</span><kbd>Ctrl + K</kbd></div><div><span>Volledig scherm</span><kbd>F11</kbd></div></div></section>
    <section className="settings-section"><div className="section-title"><ShieldCheck size={20} /><div><h2>Lokaal en in jouw handen</h2><p>Geen Nexus-account. Geen telemetrie.</p></div></div><p className="settings-prose">Je indeling, notities en bibliotheek worden op deze pc opgeslagen. Discord, Spotify en WhatsApp gebruiken hun geïnstalleerde Windows-app en bestaande aanmelding. Nexus beheert hun vensters en zet ze bij afsluiten terug. Aanmelden en uitloggen doe je in de Windows-app zelf. Nexus leest geen wachtwoorden of chatberichten uit.</p><div className="settings-actions"><button className="button secondary" onClick={() => run(() => api.exportConfig()).then(done => done && null)}><Download size={15} />Indeling exporteren</button><button className="button secondary" onClick={() => run(() => api.importConfig())}><ArrowUp size={15} />Indeling importeren</button></div><p className="small-note">Een export bevat je thema, widgets en indeling. Accounts, games en notities blijven lokaal.</p><div className="settings-bottom"><span>Nexus Hub · Windows 10 / 11</span><button className="text-link danger" onClick={() => run(() => api.window('quit'))}><Power size={14} />Nexus afsluiten</button></div></section>
  </div></>;
}
function SettingRow({ label, description, checked, onChange }) { return <div className="setting-row"><div><strong>{label}</strong><p>{description}</p></div><button className={`toggle ${checked ? 'on' : ''}`} role="switch" aria-checked={checked} aria-label={label} onClick={() => onChange(!checked)} /></div>; }
function Modal({ title, onClose, children, wide }) {
  const ref = useRef();
  useEffect(() => { const before = document.activeElement; const focusable = () => [...(ref.current?.querySelectorAll('button:not([disabled]), input, select, textarea, [tabindex="0"]') || [])]; focusable()[0]?.focus(); const trap = e => { if (e.key !== 'Tab') return; const nodes = focusable(), first = nodes[0], last = nodes.at(-1); if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); } }; ref.current?.addEventListener('keydown', trap); return () => { ref.current?.removeEventListener('keydown', trap); before?.focus(); }; }, []);
  return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><div className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-label={title} ref={ref}><div className="modal-heading"><div><span className="eyebrow">NEXUS WORKSPACE</span><h2>{title}</h2></div><IconButton icon={X} label="Venster sluiten" onClick={onClose} /></div><div className="modal-content">{children}</div></div></div>;
}
function WidgetPicker({ state, layout, updateLayout, run }) {
  const [webName, setWebName] = useState(''), [webUrl, setWebUrl] = useState('');
  return <><p className="modal-description">Kies wat je wilt zien in je {profiles[state.settings.profile]}-dashboard. Je kunt alles later verplaatsen.</p><div className="widget-catalog">{Object.entries(widgetInfo).map(([id, [name, Icon, description]]) => <button key={id} className={layout.includes(id) ? 'added' : ''} onClick={() => updateLayout(layout.includes(id) ? layout.filter(w => w !== id) : [...layout, id])}><div><span className="catalog-icon"><Icon size={22} strokeWidth={1.4} /></span><span className="catalog-check">{layout.includes(id) ? <Check size={15} /> : <Plus size={15} />}</span></div><strong>{name}</strong><p>{description}</p></button>)}</div><div className="web-widget-form"><div className="section-title"><Globe size={19} /><div><h3>Voeg je eigen webwidget toe</h3><p>Bijvoorbeeld een dashboard, agenda of je favoriete website.</p></div></div><form onSubmit={e => { e.preventDefault(); run(() => api.webWidget({ name: webName, url: webUrl })).then(result => { if (result) { setWebName(''); setWebUrl(''); } }); }}><input className="text-input" aria-label="Naam van webwidget" placeholder="Naam van je widget" value={webName} onChange={e => setWebName(e.target.value)} required maxLength={50} /><input className="text-input" type="url" aria-label="Website van webwidget" placeholder="https://…" value={webUrl} onChange={e => setWebUrl(e.target.value)} required pattern="https://.*" /><button className="button primary" type="submit"><Plus size={16} />Toevoegen</button></form>{state.webWidgets.map(w => <div className="custom-widget-row" key={w.id}><Globe size={16} /><span><strong>{w.name}</strong><small>{new URL(w.url).hostname}</small></span><button className="button ghost" onClick={() => updateLayout(layout.includes(w.id) ? layout.filter(id => id !== w.id) : [...layout, w.id])}>{layout.includes(w.id) ? 'Verbergen' : 'Toevoegen'}</button><IconButton icon={Trash2} label={`${w.name} verwijderen`} onClick={() => run(() => api.removeWebWidget(w.id))} /></div>)}</div></>;
}
function AddGame({ state, run, setModal, notify }) {
  const [query, setQuery] = useState('');
  const apps = state.library.startApps.filter(a => a.name.toLowerCase().includes(query.toLowerCase()) && /^[\w.!-]+$/.test(a.appId)).slice(0, 60);
  return <><button className="file-picker" onClick={() => run(() => api.addGame()).then(result => { if (result) { setModal(null); notify('Game toegevoegd aan je bibliotheek'); } })}><Plus size={25} /><span><strong>Kies een game of snelkoppeling</strong><small>Een .exe, .lnk of .url op je computer</small></span><ArrowRight size={18} /></button><div className="or-divider"><span>OF EEN WINDOWS-APP</span></div><label className="input-search"><Search size={17} /><input autoFocus placeholder="Zoek een geïnstalleerde Windows-app…" aria-label="Windows-app zoeken" value={query} onChange={e => setQuery(e.target.value)} /></label><div className="start-app-list">{apps.map(a => <button key={a.appId} onClick={() => run(() => api.addStartApp(a.appId)).then(result => { if (result) { setModal(null); notify(`${a.name} toegevoegd`); } })}><Gamepad2 size={18} /><span>{a.name}</span><Plus size={16} /></button>)}{!apps.length && <p className="small-note">Geen apps gevonden. Scan eerst je bibliotheek of kies een bestand.</p>}</div></>;
}
function CommandSearch({ state, navigate, goService, gameLaunch, setModal }) {
  const [query, setQuery] = useState('');
  const items = [
    { id: 'home', title: 'Dashboard', detail: 'Je command center', icon: LayoutDashboard, action: () => navigate('dashboard') },
    { id: 'games', title: 'Gamebibliotheek', detail: `${state.library.games.length} games`, icon: Gamepad2, action: () => navigate('library') },
    { id: 'settings', title: 'Instellingen', detail: 'Schermen, thema’s en voorkeuren', icon: Settings2, action: () => navigate('settings') },
    ...Object.entries(state.services).map(([id, s]) => ({ id, title: s.name, detail: 'App openen', icon: serviceIcons[id], action: () => goService(id) })),
    ...state.library.games.map(g => ({ id: g.id, title: g.name, detail: g.source, icon: Gamepad2, action: () => { gameLaunch(g); setModal(null); } })),
    ...state.webWidgets.map(w => ({ id: w.id, title: w.name, detail: 'Webwidget', icon: Globe, action: () => goService(w.id) })),
  ].filter(i => `${i.title} ${i.detail}`.toLowerCase().includes(query.toLowerCase())).slice(0, 20);
  return <><label className="input-search command-input"><Search size={20} /><input autoFocus placeholder="Zoek games, apps of instellingen…" aria-label="Zoek in Nexus" value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') items[0]?.action(); }} /></label><div className="command-results">{items.map(({ id, title, detail, icon: Icon, action }) => <button key={id} onClick={action}><Icon size={19} /><span><strong>{title}</strong><small>{detail}</small></span><ArrowUpRight size={16} /></button>)}{!items.length && <Empty compact icon={Search} title="Niets gevonden" text="Probeer een andere zoekopdracht." />}</div></>;
}



